// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        // caller must be the admin (deployer of c), otherwise the call reverts in both versions
        vm.assume(caller == address(this));
        vm.prank(caller);
        c.setOwner(newOwner);
        // General rule: setOwner sets owner exactly to the requested address.
        assertTrue(c.owner() == newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public {
        c = new C();
        admin = msg.sender;
    }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != admin);
        vm.assume(newOwner != address(0));
        // admin first legitimately sets owner to the fuzzed caller
        vm.prank(admin);
        c.setOwner(caller);
        // now a non-admin (the current owner) tries to set a new owner:
        // reference must revert, buggy version succeeds and mutates owner
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "non-admin must never be able to change the owner");
    }
}

