// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        address admin = address(this); // deployer is admin in setUp's context
        vm.assume(actor != admin);
        address before = c.owner();
        vm.prank(actor);
        c.setOwner(newOwner);
        assertTrue(c.owner() == before, "non-admin must not change owner");
    }
}
